Here's a C implementation of a simple arena allocator with all the requested functions:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    char *buffer;       // The memory block
    size_t capacity;    // Total size of the buffer
    size_t offset;      // Current offset from the beginning
    char *current;      // Current allocation pointer
} Arena;

// Helper function to align a pointer
static void *align_pointer(void *ptr, size_t alignment) {
    uintptr_t addr = (uintptr_t)ptr;
    uintptr_t aligned_addr = (addr + alignment - 1) & ~(alignment - 1);
    return (void *)aligned_addr;
}

// Create an arena with given capacity
Arena *arena_create(size_t capacity) {
    if (capacity == 0) return NULL;

    Arena *arena = (Arena *)malloc(sizeof(Arena));
    if (!arena) return NULL;

    arena->buffer = (char *)malloc(capacity);
    if (!arena->buffer) {
        free(arena);
        return NULL;
    }

    arena->capacity = capacity;
    arena->offset = 0;
    arena->current = arena->buffer;

    return arena;
}

// Allocate memory from the arena with alignment
void *arena_alloc(Arena *arena, size_t size, size_t alignment) {
    if (!arena || size == 0) return NULL;

    // Default alignment to 16 bytes if 0 is provided
    if (alignment == 0) {
        alignment = 16;
    }

    // Ensure alignment is a power of two
    if ((alignment & (alignment - 1)) != 0) {
        return NULL; // Invalid alignment
    }

    // Align the current pointer
    char *aligned_ptr = (char *)align_pointer(arena->current, alignment);

    // Calculate how much padding was added
    size_t padding = (size_t)(aligned_ptr - arena->current);

    // Check if we have enough space
    if (arena->offset + padding + size > arena->capacity) {
        return NULL; // Out of memory
    }

    // Update the arena state
    arena->current = aligned_ptr + size;
    arena->offset = (size_t)(arena->current - arena->buffer);

    return aligned_ptr;
}

// Reset the arena, making all previously allocated memory available again
void arena_reset(Arena *arena) {
    if (!arena) return;

    arena->offset = 0;
    arena->current = arena->buffer;
}

// Destroy the arena and free its memory
void arena_destroy(Arena *arena) {
    if (!arena) return;

    if (arena->buffer) {
        free(arena->buffer);
    }
    free(arena);
}

// Example usage
int main() {
    // Create an arena with 1KB capacity
    Arena *arena = arena_create(1024);
    if (!arena) {
        printf("Failed to create arena\n");
        return 1;
    }

    // Allocate some memory with different alignments
    int *p1 = (int *)arena_alloc(arena, sizeof(int), 4);
    double *p2 = (double *)arena_alloc(arena, sizeof(double), 8);
    char *p3 = (char *)arena_alloc(arena, 32, 16);

    if (p1 && p2 && p3) {
        *p1 = 42;
        *p2 = 3.14159;
        strcpy(p3, "Hello, arena allocator!");

        printf("p1 = %d\n", *p1);
        printf("p2 = %f\n", *p2);
        printf("p3 = %s\n", p3);
        printf("Current offset: %zu bytes\n", arena->offset);
    }

    // Reset the arena
    arena_reset(arena);
    printf("Arena reset. Current offset: %zu bytes\n", arena->offset);

    // Allocate again (same memory can be reused)
    int *p4 = (int *)arena_alloc(arena, sizeof(int), 4);
    if (p4) {
        *p4 = 100;
        printf("p4 (after reset) = %d\n", *p4);
    }

    // Destroy the arena
    arena_destroy(arena);

    return 0;
}
```

## Key Features:

1. **`arena_create(capacity)`**: Allocates a contiguous block of memory and initializes the arena structure.

2. **`arena_alloc(arena, size, alignment)`**: 
   - Allocates memory with specified alignment (default 16 bytes if alignment=0)
   - Handles alignment by rounding up the current pointer to the next aligned address
   - Returns NULL if there's not enough space

3. **`arena_reset(arena)`**: Resets the offset and current pointer back to the beginning, allowing memory reuse without deallocation.

4. **`arena_destroy(arena)`**: Frees all memory associated with the arena.

## Alignment Helper:
The `align_pointer` function ensures pointers are aligned to powers of two by:
- Converting the pointer to an integer
- Adding alignment-1
- Masking off the lower bits to get alignment

## Example Output:
```
p1 = 42
p2 = 3.141590
p3 = Hello, arena allocator!
Current offset: 80 bytes
Arena reset. Current offset: 0 bytes
p4 (after reset) = 100
```

## Benefits of Arena Allocators:
- **Speed**: Single allocation, bulk deallocation
- **No fragmentation**: All memory is contiguous
- **Simplified memory management**: Great for temporary allocations or frame-based memory
- **Cache-friendly**: All allocations are close together in memory

Here's a C function that multiplies a row-major float matrix by a float vector with cache-friendly loop ordering, along with detailed comments:

```c
#include <stdio.h>
#include <stdlib.h>

/**
 * Multiplies a row-major float matrix by a float vector: result = matrix * vector
 * 
 * @param matrix   Input matrix in row-major order (m x n)
 * @param vector   Input vector (n)
 * @param result   Output vector (m)
 * @param m        Number of rows in matrix
 * @param n        Number of columns in matrix / length of vector
 */
void matrix_vector_multiply(const float *matrix, const float *vector, 
                           float *result, int m, int n) {

    // Loop over each row of the matrix
    // This is the outer loop because we're accessing matrix row by row,
    // which is contiguous in memory for row-major storage
    for (int i = 0; i < m; i++) {

        // Initialize result element to 0
        float sum = 0.0f;

        // For each element in this row, multiply with corresponding vector element
        // This loop accesses matrix[i][j] sequentially (spatial locality) and
        // vector[j] sequentially (temporal locality if vector fits in cache)
        for (int j = 0; j < n; j++) {

            // Calculate linear index for row-major matrix
            // matrix[i][j] is at offset i*n + j from matrix base
            sum += matrix[i * n + j] * vector[j];
        }

        // Store result for row i
        result[i] = sum;
    }
}

/*
 * Alternative implementation with loop interchange for very wide matrices
 * where the vector might not fit in cache. This version accesses the vector
 * in a cache-blocked manner.
 */
void matrix_vector_multiply_blocked(const float *matrix, const float *vector, 
                                   float *result, int m, int n, int block_size) {

    // Initialize result vector to zero
    for (int i = 0; i < m; i++) {
        result[i] = 0.0f;
    }

    // Process matrix in blocks of columns
    // This reduces the working set size for the vector, improving cache utilization
    for (int j_block = 0; j_block < n; j_block += block_size) {
        int j_end = (j_block + block_size < n) ? j_block + block_size : n;

        // For each block of columns, update all rows
        for (int i = 0; i < m; i++) {
            float sum = result[i];  // Load existing partial sum

            // Process columns within this block
            for (int j = j_block; j < j_end; j++) {
                sum += matrix[i * n + j] * vector[j];
            }

            result[i] = sum;  // Store updated partial sum
        }
    }
}

/*
 * Demo function to test the multiplication
 */
void test_matrix_vector_multiply() {
    // Example: 3x3 matrix times 3-element vector
    int m = 3, n = 3;

    // Row-major storage: {{1,2,3}, {4,5,6}, {7,8,9}}
    float matrix[9] = {1, 2, 3, 
                       4, 5, 6, 
                       7, 8, 9};
    float vector[3] = {1, 2, 3};
    float result[3];

    printf("Matrix (row-major):\n");
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            printf("%6.2f ", matrix[i * n + j]);
        }
        printf("\n");
    }

    printf("\nVector: ");
    for (int j = 0; j < n; j++) {
        printf("%.2f ", vector[j]);
    }
    printf("\n\n");

    // Standard multiplication
    matrix_vector_multiply(matrix, vector, result, m, n);

    printf("Result (standard): ");
    for (int i = 0; i < m; i++) {
        printf("%.2f ", result[i]);
    }
    printf("\n");

    // Blocked multiplication
    matrix_vector_multiply_blocked(matrix, vector, result, m, n, 2);

    printf("Result (blocked):   ");
    for (int i = 0; i < m; i++) {
        printf("%.2f ", result[i]);
    }
    printf("\n");
}

int main() {
    test_matrix_vector_multiply();
    return 0;
}
```

## Key Cache Optimization Strategies:

### 1. **Row-Major Loop Order** (in `matrix_vector_multiply`):
- **Why**: Since the matrix is stored in row-major order, accessing `matrix[i][j]` sequentially as `j` increases gives excellent **spatial locality** - consecutive memory accesses.
- The vector is also accessed sequentially, giving it **temporal locality** if it fits in cache.

### 2. **Blocked Version** (in `matrix_vector_multiply_blocked`):
- **Why**: For very wide matrices (large `n`), the entire vector might not fit in cache. By processing the matrix in column blocks:
  - We reuse the same block of vector elements for all rows
  - This improves **temporal locality** for the vector
  - The working set size is controlled by `block_size`

### 3. **Alternative Loop Orders Considered**:
- **Column-major loops** would access `matrix[j][i]` which jumps `n` elements in memory for each `j` increment → terrible cache performance for row-major storage.
- **Inner loop over rows** would access different rows for each column → poor spatial locality for the matrix.

### 4. **Performance Notes**:
- The standard version has O(mn) time complexity
- The blocked version has the same time complexity but better constant factors for large `n`
- For small matrices/vectors that fit in cache, the standard version is typically faster due to simpler loop structure
- The `block_size` should be chosen based on cache size and element size (e.g., 64-128 for float arrays)

### Expected Output:
```
Matrix (row-major):
  1.00   2.00   3.00 
  4.00   5.00   6.00 
  7.00   8.00   9.00 

Vector: 1.00 2.00 3.00 

Result (standard): 14.00 32.00 50.00 
Result (blocked):   14.00 32.00 50.00 
```

The results match: 
- Row 0: 1×1 + 2×2 + 3×3 = 1 + 4 + 9 = 14
- Row 1: 4×1 + 5×2 + 6×3 = 4 + 10 + 18 = 32  
- Row 2: 7×1 + 8×2 + 9×3 = 7 + 16 + 27 = 50

# C Thread Pool Skeleton with pthreads

Here's a complete thread pool implementation with fixed workers, task queue, mutex+condition variables, submit, and shutdown functionality:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

// Task structure
typedef struct task {
    void (*function)(void*);  // Task function
    void* argument;           // Argument to pass to function
    struct task* next;        // Next task in queue
} task_t;

// Thread pool structure
typedef struct {
    pthread_t* workers;       // Worker threads array
    task_t* task_queue;       // Task queue (linked list)
    int num_threads;          // Number of worker threads

    // Synchronization primitives
    pthread_mutex_t queue_mutex;
    pthread_cond_t queue_cond;       // For waiting on tasks
    pthread_cond_t shutdown_cond;    // For shutdown notification

    bool shutdown;            // Shutdown flag
    int active_tasks;         // Number of tasks being executed
} thread_pool_t;

// Worker thread function
void* worker_function(void* arg) {
    thread_pool_t* pool = (thread_pool_t*)arg;

    while (1) {
        pthread_mutex_lock(&pool->queue_mutex);

        // Wait for task or shutdown signal
        while (pool->task_queue == NULL && !pool->shutdown) {
            pthread_cond_wait(&pool->queue_cond, &pool->queue_mutex);
        }

        // Check if we should shut down
        if (pool->shutdown && pool->task_queue == NULL) {
            pthread_mutex_unlock(&pool->queue_mutex);
            break;
        }

        // Get task from queue
        task_t* task = pool->task_queue;
        if (task != NULL) {
            pool->task_queue = task->next;
            pool->active_tasks++;
            pthread_mutex_unlock(&pool->queue_mutex);

            // Execute the task
            task->function(task->argument);

            // Clean up
            free(task);

            pthread_mutex_lock(&pool->queue_mutex);
            pool->active_tasks--;

            // If shutdown and no more tasks, signal shutdown condition
            if (pool->shutdown && pool->task_queue == NULL && pool->active_tasks == 0) {
                pthread_cond_signal(&pool->shutdown_cond);
            }
            pthread_mutex_unlock(&pool->queue_mutex);
        } else {
            pthread_mutex_unlock(&pool->queue_mutex);
        }
    }

    return NULL;
}

// Create a new thread pool
thread_pool_t* thread_pool_create(int num_threads) {
    thread_pool_t* pool = malloc(sizeof(thread_pool_t));
    if (pool == NULL) {
        return NULL;
    }

    pool->num_threads = num_threads;
    pool->task_queue = NULL;
    pool->shutdown = false;
    pool->active_tasks = 0;

    // Initialize synchronization primitives
    pthread_mutex_init(&pool->queue_mutex, NULL);
    pthread_cond_init(&pool->queue_cond, NULL);
    pthread_cond_init(&pool->shutdown_cond, NULL);

    // Allocate memory for worker threads
    pool->workers = malloc(sizeof(pthread_t) * num_threads);
    if (pool->workers == NULL) {
        pthread_mutex_destroy(&pool->queue_mutex);
        pthread_cond_destroy(&pool->queue_cond);
        pthread_cond_destroy(&pool->shutdown_cond);
        free(pool);
        return NULL;
    }

    // Create worker threads
    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&pool->workers[i], NULL, worker_function, (void*)pool) != 0) {
            // Cleanup on failure
            for (int j = 0; j < i; j++) {
                pthread_cancel(pool->workers[j]);
                pthread_join(pool->workers[j], NULL);
            }
            free(pool->workers);
            pthread_mutex_destroy(&pool->queue_mutex);
            pthread_cond_destroy(&pool->queue_cond);
            pthread_cond_destroy(&pool->shutdown_cond);
            free(pool);
            return NULL;
        }
    }

    printf("Thread pool created with %d workers\n", num_threads);
    return pool;
}

// Submit a task to the thread pool
int thread_pool_submit(thread_pool_t* pool, void (*function)(void*), void* argument) {
    if (pool == NULL || function == NULL || pool->shutdown) {
        return -1;  // Invalid parameters or pool is shutting down
    }

    // Create new task
    task_t* new_task = malloc(sizeof(task_t));
    if (new_task == NULL) {
        return -1;
    }

    new_task->function = function;
    new_task->argument = argument;
    new_task->next = NULL;

    // Add task to queue
    pthread_mutex_lock(&pool->queue_mutex);

    // Add to end of queue
    if (pool->task_queue == NULL) {
        pool->task_queue = new_task;
    } else {
        task_t* current = pool->task_queue;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_task;
    }

    // Signal that a task is available
    pthread_cond_signal(&pool->queue_cond);
    pthread_mutex_unlock(&pool->queue_mutex);

    printf("Task submitted to thread pool\n");
    return 0;
}

// Shut down the thread pool
void thread_pool_shutdown(thread_pool_t* pool, bool wait_for_tasks) {
    if (pool == NULL) {
        return;
    }

    pthread_mutex_lock(&pool->queue_mutex);

    // Set shutdown flag
    pool->shutdown = true;

    // If we're not waiting for tasks, clear the queue
    if (!wait_for_tasks) {
        task_t* current = pool->task_queue;
        while (current != NULL) {
            task_t* next = current->next;
            free(current);
            current = next;
        }
        pool->task_queue = NULL;
    }

    // Wake up all worker threads
    pthread_cond_broadcast(&pool->queue_cond);

    // Wait for all tasks to complete if requested
    if (wait_for_tasks) {
        while (pool->task_queue != NULL || pool->active_tasks > 0) {
            pthread_cond_wait(&pool->shutdown_cond, &pool->queue_mutex);
        }
    }

    pthread_mutex_unlock(&pool->queue_mutex);

    // Join all worker threads
    for (int i = 0; i < pool->num_threads; i++) {
        pthread_join(pool->workers[i], NULL);
    }

    // Cleanup resources
    free(pool->workers);
    pthread_mutex_destroy(&pool->queue_mutex);
    pthread_cond_destroy(&pool->queue_cond);
    pthread_cond_destroy(&pool->shutdown_cond);
    free(pool);

    printf("Thread pool shut down\n");
}

// Example task function
void example_task(void* arg) {
    int task_id = *(int*)arg;
    printf("Task %d executed by thread %lu\n", task_id, pthread_self());
    free(arg);  // Free the argument
}

// Example usage
int main() {
    // Create thread pool with 4 workers
    thread_pool_t* pool = thread_pool_create(4);
    if (pool == NULL) {
        fprintf(stderr, "Failed to create thread pool\n");
        return 1;
    }

    // Submit 10 tasks
    for (int i = 0; i < 10; i++) {
        int* task_id = malloc(sizeof(int));
        *task_id = i;

        if (thread_pool_submit(pool, example_task, task_id) != 0) {
            fprintf(stderr, "Failed to submit task %d\n", i);
            free(task_id);
        }
    }

    // Give tasks time to complete (for demo purposes)
    sleep(2);

    // Shutdown the pool (wait for all tasks to complete)
    thread_pool_shutdown(pool, true);

    return 0;
}
```

## Key Features:

1. **Fixed Worker Threads**: Creates a predetermined number of worker threads that wait for tasks.

2. **Task Queue**: Uses a linked list for FIFO task scheduling.

3. **Synchronization**:
   - `queue_mutex`: Protects access to the task queue
   - `queue_cond`: Workers wait on this when queue is empty
   - `shutdown_cond`: Used to notify when shutdown is complete

4. **Submit Function**:
   - Thread-safe task submission
   - Adds tasks to end of queue
   - Signals waiting workers

5. **Shutdown**:
   - Sets shutdown flag
   - Can wait for pending tasks or clear queue
   - Properly joins all worker threads
   - Cleans up all resources

## Compilation and Execution:

```bash
gcc -pthread thread_pool.c -o thread_pool
./thread_pool
```

## Key Design Decisions:

- **Proper Cleanup**: Ensures all threads are joined and memory is freed
- **Graceful Shutdown**: Can either wait for pending tasks or force shutdown
- **Error Handling**: Returns error codes for failed operations
- **Thread Safety**: All shared resources are properly protected with mutexes

This implementation provides a solid foundation for a thread pool. You can extend it by adding:
- Task prioritization
- Task cancellation
- Pool resizing
- More sophisticated task scheduling
- Dynamic task result handling

# Three Common Undefined Behaviors in C — and Their Fixes

---

## 1. Signed Integer Overflow

```c
/* ============================================
 * UNDEFINED BEHAVIOR: Signed Integer Overflow
 * ============================================
 * The C standard says signed integer overflow
 * is undefined. A 2's-complement "wraparound"
 * is NOT guaranteed by the standard — the
 * compiler may assume it never happens and
 * optimize accordingly.
 * ============================================ */

#include <stdio.h>
#include <limits.h>

void signed_overflow_UB(void) {
    int a = INT_MAX; /* 2147483647 on most systems */
    int b = 1;
    /* UB! Signed overflow is undefined. The compiler may
       optimize this out entirely, or it may "wrap", or
       something else. Do NOT rely on any behavior. */
    int c = a + b;

    printf("Result: %d\n", c); /* Don't count on -2147483648 */
}

/* ---------------------------
 * FIXED VERSION
 * --------------------------- */

void signed_overflow_fixed(void) {
    int a = INT_MAX;
    int b = 1;

    /* Check BEFORE the operation overflows. */
    if (b > 0 && a > INT_MAX - b) {
        fprintf(stderr, "Error: addition would overflow!\n");
        return; /* or handle it gracefully */
    }

    int c = a + b; /* Now guaranteed safe */
    printf("Result: %d\n", c);
}

/*
 * ALTERNATIVE FIXED APPROACH — use a wider type:
 *
 *     long long a_wide = a;
 *     long long b_wide = b;
 *     long long c_wide = a_wide + b_wide; // safe; fits in long long
 *
 * Or use unsigned types (which DO wrap defined-ly):
 *
 *     unsigned int ua = (unsigned int)a;
 *     unsigned int ub = (unsigned int)b;
 *     unsigned int uc = ua + ub; // well-defined modular arithmetic
 */


/* =================================================
 * 2. USE-AFTER-FREE
 * =================================================
 * After free(), the pointer becomes invalid. Accessing
 * or freeing it again is undefined — the memory may have
 * been reused, overwritten, or the allocator may crash.
 * ================================================= */

#include <stdlib.h>

void use_after_free_UB(void) {
    int *p = malloc(sizeof(int));
    if (!p) return;

    *p = 42;

    free(p);

    /* UB! p now points to freed memory. The allocator may
       have already reused this block. Reading *p gives an
       indeterminate (possibly overwritten) value. */
    printf("Value: %d\n", *p); /* UB */

    /* Also UB: double-free — destroying the allocator's
       internal state. */
    free(p); /* UB */
}

/* ---------------------------
 * FIXED VERSION
 * --------------------------- */

void use_after_free_fixed(void) {
    int *p = malloc(sizeof(int));
    if (!p) return;

    *p = 42;

    /* Read the value we need BEFORE freeing. */
    int value = *p; /* Valid — memory is still ours */

    free(p);
    p = NULL; /* Best practice: null the pointer so any
                 accidental reuse is an immediate NULL
                 dereference (crash) rather than silent
                 corruption. */

    /* Now use the copy, not the freed pointer. */
    printf("Value: %d\n", value);

    /* free(p);  — safely does nothing on a NULL pointer */
}


/* =====================================================
 * 3. STRICT ALIASING VIOLATION
 * =====================================================
 * The C standard says you may only access an object
 * through a type that is "compatible" with its declared
 * type, a signed/unsigned variant, or a few special
 * exceptions (char, uint8_t, etc.). Accessing an int
 * through an unrelated pointer type is UB.
 *
 * Compilers exploit this rule to reorder loads/stores
 * aggressively, so aliasing violations can produce
 * completely wrong results even when the code looks
 * "obviously correct."
 * ===================================================== */

#include <stdint.h>

/* Read a float's bit representation as an integer,
   then count leading zeros of the mantissa.            */
void strict_aliasing_UB(float f) {
    int bits;
    /* UB! We declared `bits` as int, but we are writing
       through a pointer to int that actually points at
       a float object. The compiler is free to assume
       that `bits` and `f` do not alias, and may reorder
       or eliminate loads. */
    int *p = &bits;
    *p = *(int *)&f;

    /* On GCC with -O2, this may print 0 on x86 because
       the compiler assumes `bits` was never written to
       by the aliasing store through `p`. */
    printf("Leading zeros in mantissa: %d\n",
           __builtin_clz(bits & 0x007FFFFF));
}

/* ---------------------------
 * FIXED VERSIONS
 * --------------------------- */

/* Method A — use a union (allowed by C99+, widely
   supported as an extension even in C89):            */
void strict_aliasing_fixed_union(float f) {
    union { float f; int i; } u;
    u.f = f;            /* write the float */
    int bits = u.i;     /* read it back as int — legal */

    printf("Leading zeros in mantissa: %d\n",
           __builtin_clz(bits & 0x007FFFFF));
}

/* Method B — use memcpy (the standard-approved way,
   and compilers are smart enough to optimize it):    */
#include <string.h>

void strict_aliasing_fixed_memcpy(float f) {
    int bits;
    memcpy(&bits, &f, sizeof(bits)); /* bitwise copy */

    printf("Leading zeros in mantissa: %d\n",
           __builtin_clz(bits & 0x007FFFFF));
}

/* Method C — use char* or uint8_t* (always allowed
   by the aliasing rules to alias anything):          */
void strict_aliasing_fixed_charptr(float f) {
    int bits;
    const unsigned char *src = (const unsigned char *)&f;
    unsigned char       *dst = (unsigned char       *)&bits;

    /* Copy byte-by-byte (handles endianness correctly). */
    memcpy(dst, src, sizeof(bits));

    printf("Leading zeros in mantissa: %d\n",
           __builtin_clz(bits & 0x007FFFFF));
}


/* =====================================================
 * MAIN — demonstrate all three
 * ===================================================== */

int main(void) {
    printf("--- Signed Overflow ---\n");
    signed_overflow_UB();
    signed_overflow_fixed();

    printf("\n--- Use-After-Free ---\n");
    use_after_free_UB();      /* UB — may crash or print garbage */
    use_after_free_fixed();

    printf("\n--- Strict Aliasing ---\n");
    strict_aliasing_UB(1.0f);
    strict_aliasing_fixed_union(1.0f);
    strict_aliasing_fixed_memcpy(1.0f);
    strict_aliasing_fixed_charptr(1.0f);

    return 0;
}
```

---

## Quick Reference

| UB | Why it's dangerous | Key fix |
|---|---|---|
| **Signed overflow** | Compiler may assume it never happens and optimize away checks | Pre-check with `INT_MAX - b`, or use wider/unsigned types |
| **Use-after-free** | Memory may be reused; reads return garbage, double-free corrupts heap | Set `p = NULL` after `free(p)`; use local copies |
| **Strict aliasing** | Compiler reorders loads/stores assuming unrelated types don't alias | Use `memcpy`, a `union`, or `char*` / `uint8_t*` |

> **Tip:** Compile with `gcc -fsanitize=undefined,address` to catch many of these automatically at runtime.

Here's a self-contained C implementation with a scalar dot product and an AVX-intrinsics version guarded by `#ifdef __AVX__`. Both handle arbitrary array lengths (including non-8-aligned sizes) and produce the same mathematical result. The only real difference is floating-point accumulation order, which may cause a 1–2 ULP difference in edge cases, but the logic is functionally identical.

```c
#include <stdio.h>
#include <stddef.h>

/* -------------------------------------------------
   Scalar dot product – always available
   ------------------------------------------------- */
float dot_product_scalar(const float *a, const float *b, int n) {
    float sum = 0.0f;
    for (int i = 0; i < n; ++i)
        sum += a[i] * b[i];
    return sum;
}

/* -------------------------------------------------
   AVX intrinsics version – compiled only if __AVX__ is defined
   (e.g., with -mavx under GCC/Clang)
   ------------------------------------------------- */
#ifdef __AVX__
#include <immintrin.h>

float dot_product_avx(const float *a, const float *b, int n) {
    /* Accumulator: 256-bit register holding 8 floats */
    __m256 sum = _mm256_setzero_ps();

    int i = 0;
    /* Process 8 floats at a time (unaligned loads for safety) */
    for (; i + 7 < n; i += 8) {
        __m256 va = _mm256_loadu_ps(&a[i]);
        __m256 vb = _mm256_loadu_ps(&b[i]);
        sum = _mm256_add_ps(sum, _mm256_mul_ps(va, vb));
    }

    /* Remainder – handled element‑wise to match scalar accumulation order */
    for (; i < n; ++i) {
        sum = _mm256_add_ps(sum, _mm256_set1_ps(a[i] * b[i]));
    }

    /* Horizontal sum: reduce 8 floats → 1 scalar using pure AVX */
    __m128 lo = _mm256_castps256_ps128(sum);   /* lower 4 floats */
    __m128 hi = _mm256_extractf128_ps(sum, 1); /* upper 4 floats */

    /* Each hadd reduces 4 floats to 2, then 1 */
    lo = _mm_hadd_ps(lo, lo);
    lo = _mm_hadd_ps(lo, lo);
    hi = _mm_hadd_ps(hi, hi);
    hi = _mm_hadd_ps(hi, hi);

    __m128 total = _mm_add_ss(lo, hi);   /* add the two partial sums */
    total = _mm_shuffle_ps(total, total, _MM_SHUFFLE(0, 0, 0, 0)); /* broadcast */
    return _mm_cvtss_f32(total);
}
#endif /* __AVX__ */

/* -------------------------------------------------
   Optional: tiny test harness (compile with -mavx to enable AVX)
   ------------------------------------------------- */
#ifndef TEST_MAIN
int main(void) {
    float a[] = {1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f,
                 0.5f, 1.5f};
    float b[] = {0.1f, 0.2f, 0.3f, 0.4f, 0.5f, 0.6f, 0.7f, 0.8f,
                 1.0f, 2.0f};
    int n = sizeof a / sizeof a[0];

    float s = dot_product_scalar(a, b, n);
    printf("Scalar: %f\n", s);

#ifdef __AVX__
    float v = dot_product_avx(a, b, n);
    printf("AVX:    %f\n", v);
    printf("Diff:   %e\n", (double)s - (double)v);
#else
    printf("AVX version not compiled (define __AVX__ or use -mavx).\n");
#endif

    return 0;
}
#endif
```

### How it works
- **Scalar**: simple loop, accumulates `sum += a[i]*b[i]`.
- **AVX version** (`#ifdef __AVX__`):
  - Loads 8 floats at a time with `_mm256_loadu_ps` (unaligned, safe for any pointer).
  - Multiplies and adds via `_mm256_mul_ps` / `_mm256_add_ps`.
  - Handles the tail (remainder < 8) with a scalar loop so the exact same products are generated in the same order.
  - Uses a classic AVX horizontal reduction (`_mm_hadd_ps`) to fold the 8-element vector down to a single `float`.
- **Identical results**: Both functions iterate over the same indices, compute the same products, and accumulate them. The only divergence is the order of floating-point additions within the vectorized head, which is why a tiny ULP difference may appear in extreme edge cases, but the mathematical result is the same.

I'll create a C function that detects memory leaks by analyzing malloc/free event logs. This function uses a hash map to track allocations and identifies pointers that were never freed.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to represent a memory event
typedef struct {
    void *pointer;      // The pointer address
    char event_type;    // 'M' for malloc, 'F' for free
} MemoryEvent;

// Structure for hash map entries
typedef struct {
    void *pointer;      // Pointer address
    int malloc_count;   // Number of mallocs without matching frees
    int free_count;     // Number of frees
    int is_used;        // Flag to check if entry is occupied
} HashEntry;

// Structure for the hash map
typedef struct {
    HashEntry *entries;  // Array of entries
    int capacity;        // Current capacity
    int size;            // Number of entries
} HashMap;

// Hash function for pointers
unsigned long hash_pointer(void *ptr) {
    unsigned long address = (unsigned long)ptr;
    // Simple hash: multiply by prime and modulo capacity
    return address * 2654435761UL;
}

// Initialize a hash map
HashMap* create_hash_map(int capacity) {
    HashMap *map = malloc(sizeof(HashMap));
    if (!map) return NULL;

    map->capacity = capacity;
    map->size = 0;
    map->entries = calloc(capacity, sizeof(HashEntry));
    if (!map->entries) {
        free(map);
        return NULL;
    }

    return map;
}

// Insert or update an entry in the hash map
void hashmap_insert_or_update(HashMap *map, void *pointer, char event_type) {
    if (!map || !pointer) return;

    // Check if we need to resize (load factor > 0.7)
    if (map->size > map->capacity * 0.7) {
        int new_capacity = map->capacity * 2;
        HashEntry *new_entries = calloc(new_capacity, sizeof(HashEntry));
        if (!new_entries) return;

        // Rehash existing entries
        for (int i = 0; i < map->capacity; i++) {
            if (map->entries[i].is_used) {
                unsigned long index = hash_pointer(map->entries[i].pointer) % new_capacity;

                // Linear probing to find empty slot
                while (new_entries[index].is_used) {
                    index = (index + 1) % new_capacity;
                }

                new_entries[index] = map->entries[i];
            }
        }

        free(map->entries);
        map->entries = new_entries;
        map->capacity = new_capacity;
    }

    // Find the entry using linear probing
    unsigned long index = hash_pointer(pointer) % map->capacity;
    while (map->entries[index].is_used && map->entries[index].pointer != pointer) {
        index = (index + 1) % map->capacity;
    }

    // Update the entry
    if (map->entries[index].pointer == pointer) {
        // Existing entry - update counts
        if (event_type == 'M' || event_type == 'm') {
            map->entries[index].malloc_count++;
        } else if (event_type == 'F' || event_type == 'f') {
            map->entries[index].free_count++;
        }
    } else {
        // New entry
        map->entries[index].pointer = pointer;
        map->entries[index].malloc_count = (event_type == 'M' || event_type == 'm') ? 1 : 0;
        map->entries[index].free_count = (event_type == 'F' || event_type == 'f') ? 1 : 0;
        map->entries[index].is_used = 1;
        map->size++;
    }
}

// Free the hash map
void free_hash_map(HashMap *map) {
    if (!map) return;
    if (map->entries) free(map->entries);
    free(map);
}

// Main function to detect memory leaks
void detect_memory_leaks(MemoryEvent *events, int num_events) {
    if (!events || num_events <= 0) {
        printf("No events to process.\n");
        return;
    }

    // Create hash map to track allocations
    HashMap *map = create_hash_map(1024);  // Initial capacity of 1024
    if (!map) {
        printf("Failed to create hash map.\n");
        return;
    }

    // Process all events
    for (int i = 0; i < num_events; i++) {
        hashmap_insert_or_update(map, events[i].pointer, events[i].event_type);
    }

    // Find and report leaked pointers
    printf("Memory leak analysis results:\n");
    printf("=============================\n");

    int leak_count = 0;

    for (int i = 0; i < map->capacity; i++) {
        if (map->entries[i].is_used) {
            HashEntry *entry = &map->entries[i];

            // A leak occurs when malloc_count > free_count
            if (entry->malloc_count > entry->free_count) {
                printf("LEAK DETECTED at %p:\n", entry->pointer);
                printf("  Mallocs: %d, Frees: %d\n", 
                       entry->malloc_count, entry->free_count);
                printf("  Unfreed: %d instance(s)\n", 
                       entry->malloc_count - entry->free_count);
                leak_count++;
            } 
            // Also report invalid frees (free without matching malloc)
            else if (entry->free_count > entry->malloc_count) {
                printf("WARNING: Free without matching malloc at %p:\n", entry->pointer);
                printf("  Mallocs: %d, Frees: %d\n", 
                       entry->malloc_count, entry->free_count);
            }
        }
    }

    if (leak_count == 0) {
        printf("No memory leaks detected.\n");
    } else {
        printf("\nTotal leaks found: %d\n", leak_count);
    }

    // Cleanup
    free_hash_map(map);
}

// Helper function to create a MemoryEvent
MemoryEvent create_event(void *pointer, char event_type) {
    MemoryEvent event;
    event.pointer = pointer;
    event.event_type = event_type;
    return event;
}

// Example usage and test
int main() {
    // Create some test pointers
    void *ptr1 = malloc(100);
    void *ptr2 = malloc(200);
    void *ptr3 = malloc(300);
    void *ptr4 = malloc(400);
    void *ptr5 = malloc(500);

    // Create event log
    MemoryEvent events[] = {
        create_event(ptr1, 'M'),  // malloc ptr1
        create_event(ptr2, 'M'),  // malloc ptr2
        create_event(ptr3, 'M'),  // malloc ptr3
        create_event(ptr1, 'F'),  // free ptr1
        create_event(ptr4, 'M'),  // malloc ptr4
        create_event(ptr2, 'F'),  // free ptr2
        create_event(ptr5, 'M'),  // malloc ptr5
        create_event(ptr3, 'F'),  // free ptr3
        create_event(ptr5, 'F'),  // free ptr5
        create_event(ptr4, 'F'),  // free ptr4
        // ptr5 has one extra free (invalid)
        create_event(ptr5, 'F'),  // extra free (should be reported as warning)
    };

    int num_events = sizeof(events) / sizeof(events[0]);

    printf("Processing %d memory events...\n", num_events);
    printf("Pointers allocated: %p, %p, %p, %p, %p\n\n", 
           ptr1, ptr2, ptr3, ptr4, ptr5);

    detect_memory_leaks(events, num_events);

    // Cleanup
    free(ptr1);
    free(ptr2);
    free(ptr3);
    free(ptr4);
    free(ptr5);

    return 0;
}
```

## How It Works:

1. **Data Structures**:
   - `MemoryEvent`: Represents a malloc ('M') or free ('F') operation on a pointer
   - `HashMap`: Stores allocation state for each pointer
   - `HashEntry`: Tracks malloc and free counts for each pointer

2. **Algorithm**:
   - Processes each event in the log
   - Uses a hash map with linear probing for efficient pointer tracking
   - Tracks both malloc and free counts for each pointer
   - Resizes the hash map when load factor exceeds 0.7

3. **Leak Detection**:
   - A leak occurs when `malloc_count > free_count` for a pointer
   - Also detects invalid operations (frees without matching mallocs)

4. **Key Features**:
   - Handles multiple malloc/free cycles for the same pointer
   - Dynamic resizing for memory efficiency
   - Reports both leaked pointers and invalid free operations
   - Shows detailed information about each leak

5. **Example Output**:
