Here's a complete C implementation of a dynamic array (vector) for integers with all the requested features:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} Vector;

// Helper function to create a new vector
Vector* vector_create(size_t initial_capacity) {
    Vector *vec = (Vector *)malloc(sizeof(Vector));
    if (!vec) return NULL;

    vec->size = 0;
    vec->capacity = initial_capacity > 0 ? initial_capacity : 1;  // Start with at least 1 capacity

    if (initial_capacity > 0) {
        vec->data = (int *)malloc(initial_capacity * sizeof(int));
        if (!vec->data) {
            free(vec);
            return NULL;
        }
    } else {
        vec->data = NULL;
    }

    return vec;
}

// Helper function to destroy the vector and free memory
void vector_destroy(Vector *vec) {
    if (vec) {
        free(vec->data);
        free(vec);
    }
}

// Helper function to print vector contents (for debugging)
void vector_print(Vector *vec) {
    printf("Vector: [");
    for (size_t i = 0; i < vec->size; i++) {
        printf("%d", vec->data[i]);
        if (i < vec->size - 1) printf(", ");
    }
    printf("] (size=%zu, capacity=%zu)\n", vec->size, vec->capacity);
}

// Push element to the end with amortized O(1) growth
int vector_push(Vector *vec, int value) {
    if (!vec) return 0;

    // Check if we need to grow
    if (vec->size >= vec->capacity) {
        size_t new_capacity = vec->capacity == 0 ? 1 : vec->capacity * 2;  // Double capacity

        // Reserve the new capacity
        if (!vector_reserve(vec, new_capacity)) {
            return 0;
        }
    }

    vec->data[vec->size] = value;
    vec->size++;
    return 1;
}

// Remove the last element
int vector_pop(Vector *vec, int *value) {
    if (!vec || vec->size == 0) return 0;

    vec->size--;

    // Optionally return the popped value
    if (value) {
        *value = vec->data[vec->size];
    }

    return 1;
}

// Reserve at least the specified capacity
int vector_reserve(Vector *vec, size_t new_capacity) {
    if (!vec) return 0;

    // Only reallocate if we need more space
    if (new_capacity <= vec->capacity) {
        return 1;
    }

    int *new_data = (int *)realloc(vec->data, new_capacity * sizeof(int));
    if (!new_data) {
        return 0;  // Allocation failed
    }

    vec->data = new_data;
    vec->capacity = new_capacity;

    return 1;
}

// Shrink capacity to fit current size
int vector_shrink_to_fit(Vector *vec) {
    if (!vec) return 0;

    size_t new_capacity = vec->size == 0 ? 0 : vec->size;

    // If size is 0, we can free the data pointer
    if (vec->size == 0) {
        free(vec->data);
        vec->data = NULL;
        vec->capacity = 0;
        return 1;
    }

    // Only reallocate if capacity is greater than size
    if (vec->capacity > vec->size) {
        int *new_data = (int *)realloc(vec->data, new_capacity * sizeof(int));
        if (!new_data) {
            return 0;  // Allocation failed (shouldn't happen for shrinking, but possible)
        }

        vec->data = new_data;
        vec->capacity = new_capacity;
    }

    return 1;
}

// Example usage
int main() {
    printf("Creating vector...\n");
    Vector *vec = vector_create(0);

    printf("Pushing elements 0-9...\n");
    for (int i = 0; i < 10; i++) {
        vector_push(vec, i);
        printf("After push %d: ", i);
        vector_print(vec);
    }

    printf("\nPopping 3 elements...\n");
    for (int i = 0; i < 3; i++) {
        int value;
        vector_pop(vec, &value);
        printf("Popped %d: ", value);
        vector_print(vec);
    }

    printf("\nReserving capacity for 20 elements...\n");
    vector_reserve(vec, 20);
    vector_print(vec);

    printf("\nPushing 5 more elements...\n");
    for (int i = 100; i < 105; i++) {
        vector_push(vec, i);
    }
    vector_print(vec);

    printf("\nShrinking to fit...\n");
    vector_shrink_to_fit(vec);
    vector_print(vec);

    printf("\nCleaning up...\n");
    vector_destroy(vec);

    return 0;
}
```

## Key Features Explained:

1. **Amortized O(1) Push**: When capacity is exhausted, we double the capacity. This ensures that while occasional reallocations are O(n), they happen so rarely that the average cost per push is O(1).

2. **Reserve**: Allows you to pre-allocate memory to avoid frequent reallocations when you know you'll need a certain capacity.

3. **Shrink to Fit**: Reduces the allocated memory to match the current size, which is useful for freeing excess memory.

4. **Memory Management**: 
   - The vector starts with a capacity of 1 if no initial capacity is specified
   - All allocations use `malloc`/`realloc`/`free`
   - The `vector_destroy` function properly frees all allocated memory

5. **Operations**:
   - `vector_push`: Adds an element to the end, growing capacity if needed
   - `vector_pop`: Removes the last element and optionally returns its value
   - `vector_reserve`: Ensures minimum capacity
   - `vector_shrink_to_fit`: Reduces capacity to match size

## Growth Strategy:
The implementation uses the classic doubling strategy for amortized O(1) push operations:
- When the vector is full, the capacity is doubled
- This results in occasional O(n) reallocations
- But the amortized cost across many operations is O(1)

## Example Output:
When you run the program, you'll see the vector growing dynamically as elements are pushed, showing the capacity doubling when needed, and properly shrinking when requested.

Here's a numerically stable in-place softmax function in C:

```c
#include <math.h>
#include <float.h>

void softmax_inplace(float *arr, int n) {
    if (n <= 0) return;

    // Find maximum value for numerical stability
    float max_val = -FLT_MAX;
    for (int i = 0; i < n; i++) {
        if (arr[i] > max_val) {
            max_val = arr[i];
        }
    }

    // Subtract max and compute exponentials
    float sum = 0.0f;
    for (int i = 0; i < n; i++) {
        arr[i] = expf(arr[i] - max_val);
        sum += arr[i];
    }

    // Normalize by dividing by sum
    for (int i = 0; i < n; i++) {
        arr[i] /= sum;
    }
}
```

## Key Features

1. **Numerically stable**: By subtracting the maximum value before exponentiation, we prevent overflow/underflow issues that could occur with very large or very small values.

2. **In-place operation**: Modifies the input array directly without requiring additional memory allocation.

3. **Single pass optimization**: We find the maximum in the first pass, then compute exponentials and their sum in the second pass, and finally normalize in the third pass.

## Usage Example

```c
#include <stdio.h>

int main() {
    float values[] = {1.0f, 2.0f, 3.0f, 4.0f, 5.0f};
    int n = sizeof(values) / sizeof(values[0]);

    printf("Before softmax: ");
    for (int i = 0; i < n; i++) {
        printf("%.2f ", values[i]);
    }
    printf("\n");

    softmax_inplace(values, n);

    printf("After softmax:  ");
    for (int i = 0; i < n; i++) {
        printf("%.4f ", values[i]);
    }
    printf("\n");

    // Verify sum is approximately 1.0
    float sum = 0.0f;
    for (int i = 0; i < n; i++) sum += values[i];
    printf("Sum of probabilities: %.6f\n", sum);

    return 0;
}
```

## Output

```
Before softmax: 1.00 2.00 3.00 4.00 5.00 
After softmax:  0.0117 0.0317 0.0861 0.2341 0.6364 
Sum of probabilities: 1.000000
```

## Alternative (Two-pass Version)

If you prefer a slightly more compact version with one less loop, you can combine the exponential calculation and sum computation:

```c
#include <math.h>
#include <float.h>

void softmax_inplace_v2(float *arr, int n) {
    if (n <= 0) return;

    // Find maximum value for numerical stability
    float max_val = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max_val) max_val = arr[i];
    }

    // Compute exponentials and sum in one pass
    float sum = 0.0f;
    for (int i = 0; i < n; i++) {
        arr[i] = expf(arr[i] - max_val);
        sum += arr[i];
    }

    // Normalize
    for (int i = 0; i < n; i++) {
        arr[i] /= sum;
    }
}
```

Both versions are numerically stable and efficient. The first version explicitly separates the max-finding from the exponential computation, which can be clearer and might allow for better compiler optimizations on some architectures.

Here's a C function that parallelizes an independent loop over N items across T threads using pthreads:

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

// Structure to pass arguments to thread function
typedef struct {
    int thread_id;          // Thread identifier
    int start_index;        // Start index for this thread's chunk
    int end_index;          // End index for this thread's chunk
    void (*work_func)(int); // Function to process each item
} ThreadArg;

// Thread worker function
void* thread_worker(void* arg) {
    ThreadArg* thread_arg = (ThreadArg*)arg;

    // Process assigned range of items
    for (int i = thread_arg->start_index; i < thread_arg->end_index; i++) {
        thread_arg->work_func(i);  // Call the user-provided work function
    }

    free(arg);  // Free the argument structure
    pthread_exit(NULL);
}

// Main parallel loop function
void parallel_loop(int N, int T, void (*work_func)(int)) {
    if (N <= 0 || T <= 0) {
        fprintf(stderr, "Error: Invalid N or T values\n");
        return;
    }

    // Limit threads to available hardware threads if T is too large
    // (You could use sysconf(_SC_NPROCESSORS_ONLN) for more precise detection)
    int actual_threads = (T > N) ? N : T;

    pthread_t* threads = (pthread_t*)malloc(actual_threads * sizeof(pthread_t));
    if (!threads) {
        perror("Failed to allocate threads array");
        return;
    }

    // Calculate items per thread
    int items_per_thread = N / actual_threads;
    int remaining_items = N % actual_threads;

    // Create threads
    for (int i = 0; i < actual_threads; i++) {
        ThreadArg* arg = (ThreadArg*)malloc(sizeof(ThreadArg));
        if (!arg) {
            perror("Failed to allocate thread argument");
            // Clean up already created threads
            for (int j = 0; j < i; j++) {
                pthread_join(threads[j], NULL);
            }
            free(threads);
            return;
        }

        // Assign chunk to this thread
        arg->thread_id = i;
        arg->start_index = i * items_per_thread + (i < remaining_items ? i : remaining_items);
        arg->end_index = arg->start_index + items_per_thread + (i < remaining_items ? 1 : 0);
        arg->work_func = work_func;

        // Create the thread
        int rc = pthread_create(&threads[i], NULL, thread_worker, arg);
        if (rc) {
            fprintf(stderr, "Error: Could not create thread %d (error %d)\n", i, rc);
            free(arg);
            // Continue creating other threads
        }
    }

    // Join all threads
    for (int i = 0; i < actual_threads; i++) {
        int rc = pthread_join(threads[i], NULL);
        if (rc) {
            fprintf(stderr, "Warning: Thread %d join failed (error %d)\n", i, rc);
        }
    }

    free(threads);
}

// Example usage - work function that processes each item
void process_item(int item_index) {
    printf("Thread %lu processing item %d\n", (unsigned long)pthread_self(), item_index);
    // Simulate some work
    usleep(100000);  // Sleep 100ms
}

int main() {
    int N = 20;  // Number of items
    int T = 4;   // Number of threads

    printf("Processing %d items with %d threads\n", N, T);
    parallel_loop(N, T, process_item);
    printf("All items processed\n");

    return 0;
}
```

## Key Features:

1. **Work Distribution**: Uses block distribution where each thread gets a contiguous chunk of items. Handles remainder items by distributing them to the first few threads.

2. **Error Handling**: Includes error checking for memory allocation and thread creation.

3. **Cleanup**: Properly cleans up resources if errors occur during setup.

4. **Flexibility**: Accepts any work function that takes an item index.

5. **Thread Limiting**: Automatically limits threads to N if T > N (no point in having more threads than work items).

## How to Compile:
```bash
gcc -pthread parallel_loop.c -o parallel_loop
```

## Customization Options:

- **Dynamic Work Distribution**: For uneven work per item, you could implement a work queue instead of static chunking.
- **Hardware Detection**: Use `sysconf(_SC_NPROCESSORS_ONLN)` to detect available CPU cores.
- **Return Values**: Modify to collect results from each thread if needed.
- **Cancellation**: Add cancellation points if you need to stop early.

The function assumes the work items are independent and can be processed in any order without synchronization requirements.

Here's a concise, overflow-safe C implementation that returns the **insertion point** (lower-bound position) for a target value in a sorted integer array. If the value exists, it returns the index of the first occurrence; if missing, it returns the index where it would be inserted to maintain sorted order.

```c
#include <stdio.h>

/**
 * binary_search_insert - Returns the lower-bound insertion index for target.
 * @arr:       Sorted array of integers (ascending order)
 * @n:         Number of elements in arr
 * @target:    Value to search or insert
 *
 * Return: Index in [0, n] where target is or should be inserted.
 *         Returns n if target > all elements.
 *         Uses overflow-safe midpoint computation.
 */
int binary_search_insert(const int arr[], int n, int target) {
    int low = 0;
    int high = n;  /* high is exclusive */

    while (low < high) {
        /* Overflow-safe: avoids (low + high) potential overflow */
        int mid = low + (high - low) / 2;

        if (arr[mid] < target)
            low = mid + 1;
        else
            high = mid;
    }
    return low;
}

/* Small test driver */
int main(void) {
    int arr[] = {10, 20, 30, 40, 50};
    int n = sizeof(arr) / sizeof(arr[0]);

    printf("insert pos for 30 (present) : %d\n", binary_search_insert(arr, n, 30));  /* 2 */
    printf("insert pos for 25 (missing) : %d\n", binary_search_insert(arr, n, 25));  /* 2 */
    printf("insert pos for 5  (below all): %d\n", binary_search_insert(arr, n, 5));   /* 0 */
    printf("insert pos for 60 (above all): %d\n", binary_search_insert(arr, n, 60));  /* 5 */
    printf("insert pos for 20 (exact)   : %d\n", binary_search_insert(arr, n, 20));   /* 1 */

    /* Empty array edge case */
    printf("insert pos in empty arr      : %d\n", binary_search_insert((const int[]){}, 0, 1));

    return 0;
}
```

### Key design choices
- **`while (low < high)`** with **exclusive upper bound** (`high = n`) is the canonical pattern for `lower_bound` / insertion-point binary search.
- **Midpoint safety**: `mid = low + (high - low) / 2` guarantees no integer overflow, even when `low` and `high` are near `INT_MAX`.
- **Returns `0` to `n`**: `0` means insert at the front; `n` means append at the end.
- Works correctly with duplicates (returns the first valid position), and handles empty arrays gracefully.

Here's a complete, robust C implementation that meets all the requirements:

- Tokenizes by whitespace without modifying the input
- Returns a dynamically allocated array of `char*` (copied tokens)
- Provides a dedicated cleanup function
- Handles edge cases (NULL input, empty string, consecutive whitespaces, allocation failures)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/* 
 * Tokenizes a string by whitespace into an array of strings.
 * Does NOT modify the input string.
 * 
 * @param input   The string to tokenize (must not be modified).
 * @param count   Output parameter: receives the number of tokens.
 * @return        Array of token strings (must be freed via free_tokens()),
 *                or NULL on error/invalid input. Sets count to 0 if no tokens.
 */
char** tokenize_by_whitespace(const char* input, int* count) {
    if (!input || !count) return NULL;

    /* First pass: count tokens and validate boundaries */
    int num_tokens = 0;
    const char* p = input;

    while (*p) {
        /* Skip leading whitespace */
        while (*p && isspace((unsigned char)*p)) p++;
        if (!*p) break;

        num_tokens++;

        /* Consume the token */
        while (*p && !isspace((unsigned char)*p)) p++;
    }

    if (num_tokens == 0) {
        *count = 0;
        return NULL;   /* no tokens – return NULL or could allocate {NULL} */
    }

    /* Second pass: allocate array and copy each token */
    char** tokens = (char**)malloc(num_tokens * sizeof(char*));
    if (!tokens) {
        *count = 0;
        return NULL;
    }

    *count = num_tokens;
    int i = 0;
    p = input;

    while (*p) {
        /* Skip whitespace */
        while (*p && isspace((unsigned char)*p)) p++;
        if (!*p) break;

        const char* start = p;

        /* Advance to end of token */
        while (*p && !isspace((unsigned char)*p)) p++;
        size_t len = (size_t)(p - start);

        /* Allocate and copy */
        tokens[i] = (char*)malloc(len + 1);
        if (!tokens[i]) {
            /* Cleanup on failure: free previously allocated tokens and the array */
            for (int j = 0; j < i; j++) free(tokens[j]);
            free(tokens);
            *count = i;   /* partial count */
            return NULL;
        }
        memcpy(tokens[i], start, len);
        tokens[i][len] = '\0';
        i++;
    }

    return tokens;
}

/* 
 * Frees all memory allocated by tokenize_by_whitespace().
 * 
 * @param tokens  Array of strings returned by tokenize_by_whitespace().
 * @param count   Number of tokens (as returned by tokenize_by_whitespace).
 */
void free_tokens(char** tokens, int count) {
    if (!tokens) return;
    for (int i = 0; i < count; i++) {
        free(tokens[i]);
    }
    free(tokens);
}

/* ---------------------------------------------------------
 * Optional: tiny demo/main to show usage
 * --------------------------------------------------------- */
#ifdef TEST_MAIN
int main(void) {
    const char* s = "  Hello   world!\tThis is a test.\n";
    int count = 0;
    char** tokens = tokenize_by_whitespace(s, &count);

    if (!tokens) {
        printf("Tokenization failed or empty input.\n");
        return 1;
    }

    printf("Input: \"%s\"\n", s);
    printf("Tokens (%d):\n", count);
    for (int i = 0; i < count; i++) {
        printf("  %d: \"%s\"\n", i, tokens[i]);
    }

    free_tokens(tokens, count);
    return 0;
}
#endif
```

### Key Design Decisions
1. **Two-pass approach**: First pass counts tokens, second pass allocates and copies substrings. This avoids modifying the input and makes error cleanup straightforward.
2. **`isspace()` with `(unsigned char)` cast**: Guarantees defined behavior for all `char` encodings per the C standard.
3. **Consecutive whitespaces treated as one delimiter**: Standard tokenization behavior (like `strtok` but without modifying the input).
4. **No empty tokens**: Leading, trailing, and multiple consecutive whitespaces are collapsed.
5. **Allocation failure safety**: If `malloc` fails mid-way, all previously allocated tokens and the array itself are freed, and `count` is set to the partial count so the caller can clean up safely.
6. **`free_tokens()`**: Single-point cleanup that frees each token string and the pointer array itself.

Call it like:
```c
int n;
char** tokens = tokenize_by_whitespace("hello world  foo", &n);
// use tokens[0..n-1]
free_tokens(tokens, n);
```

Here's a self-contained POSIX C function that memory-maps a file read-only using `mmap`, with a clean fallback to `fread`/`malloc` if the mapping fails. The interface uniformly returns a buffer and size, and an optional flag tells the caller which allocation method was used so the memory can be released correctly.

```c
/**
 * map_file_readonly - Read a file into memory using mmap, falling back to fread.
 * @path:       Path to the file to read.
 * @out_buf:    Pointer to store the resulting buffer (mapped or heap-allocated).
 * @out_size:   Pointer to store the file size on success.
 * @out_mmap:   Optional pointer to store 1 if mmap was used, 0 if fread fallback.
 *
 * Returns: 0 on success, -1 on failure (with @out_buf set to NULL).
 *
 * The caller must release the buffer using release_file_buffer(). This helper
 * knows whether to munmap() or free() based on the @out_mmap flag (or you can
 * track it yourself).
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>

int map_file_readonly(const char *path, void **out_buf, size_t *out_size, int *out_mmap) {
    if (!path || !out_buf || !out_size)
        return -1;

    /* Open file read-only */
    int fd = open(path, O_RDONLY);
    if (fd == -1)
        return -1;

    /* Get file size */
    struct stat st;
    if (fstat(fd, &st) == -1) {
        close(fd);
        return -1;
    }

    size_t size = st.st_size;

    /* Empty file – nothing to map/read */
    if (size == 0) {
        *out_buf = NULL;
        *out_size = 0;
        if (out_mmap) *out_mmap = 0;
        close(fd);
        return 0;
    }

    /* ---------- Try POSIX mmap ---------- */
    void *ptr = mmap(NULL, size, PROT_READ, MAP_SHARED, fd, 0);
    if (ptr != MAP_FAILED) {
        *out_buf = ptr;
        *out_size = size;
        if (out_mmap) *out_mmap = 1;
        close(fd);
        return 0;   /* caller should munmap() later */
    }

    /* ---------- Fallback: fread + malloc ---------- */
    close(fd);
    FILE *f = fopen(path, "rb");
    if (!f) return -1;

    void *buf = malloc(size);
    if (!buf) {
        fclose(f);
        return -1;
    }

    size_t read = fread(buf, 1, size, f);
    fclose(f);
    if (read != size) {
        free(buf);
        return -1;
    }

    *out_buf = buf;
    *out_size = size;
    if (out_mmap) *out_mmap = 0;
    return 0;   /* caller should free() later */
}

/* ---------------------------------------------------------------------- */
/* Helper to release the buffer – chooses munmap() or free() automatically   */
/* ---------------------------------------------------------------------- */
void release_file_buffer(void *buf, size_t size, int mmap) {
    if (!buf) return;
    if (mmap)
        munmap(buf, size);
    else
        free(buf);
}
```

### Usage Example
```c
void *data = NULL;
size_t sz = 0;
int mmapped = 0;

if (map_file_readonly("example.txt", &data, &sz, &mmapped) == 0) {
    /* Use data[0..sz-1] */
    if (mmapped)
        /* memory-mapped, use directly, then */
        release_file_buffer(data, sz, 1);
    else
        /* heap-allocated via fread fallback, then */
        release_file_buffer(data, sz, 0);
} else {
    /* handle error */
}
```

### Design notes
- **First attempt**: `open()` → `fstat()` → `mmap()` with `PROT_READ | MAP_SHARED`. This gives the kernel-backed, zero-copy read-only view.
- **Fallback**: If `mmap` returns `MAP_FAILED` (e.g., permission restrictions, kernel limits, or the process lacks `mmap` capability), the function closes the fd, opens the file with `fopen`, reads the entire contents into a `malloc`'d buffer via `fread`, and returns that.
- **Uniform interface**: The caller always receives a valid pointer and size. An optional `out_mmap` flag disambiguates the cleanup method, but the function works even without it (you’d just need to track the allocation method separately or always use `release_file_buffer` with a known flag).
- **Error handling**: All system calls are checked. On any failure, the function returns `-1` and leaves `*out_buf` as `NULL`.
- **Empty files**: Handled gracefully – returns a `NULL` buffer with size `0`.

Here's the canonical C error-handling pattern using `goto` for centralized resource cleanup. The idiom acquires resources step-by-step, jumps to a single `cleanup` label on any failure, and ensures every acquired resource is released exactly once.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
 * Reads entire file into a newly allocated buffer.
 * Returns 0 on success, -1 on error.
 * Sets *out_buffer and *out_size on success; caller owns the buffer.
 */
int read_whole_file(const char *path, char **out_buffer, size_t *out_size) {
    FILE *f = NULL;
    char *buf = NULL;
    long size;
    int result = -1;

    /* ---- acquisition phase ---- */
    f = fopen(path, "rb");
    if (f == NULL) goto cleanup;

    fseek(f, 0, SEEK_END);
    size = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (size < 0) goto cleanup;          /* ferror or encoding issue */

    buf = malloc((size_t)size);
    if (buf == NULL) goto cleanup;      /* out of memory */

    if (fread(buf, 1, (size_t)size, f) != (size_t)size) goto cleanup; /* read error */

    /* ---- success: transfer ownership ---- */
    *out_buffer = buf;
    *out_size = (size_t)size;
    buf = NULL;                          /* prevent cleanup from freeing it */
    result = 0;

    /* ---- cleanup (only reached on failure) ---- */
cleanup:
    if (buf) free(buf);                   /* no-op if buf was transferred */
    if (f) fclose(f);
    return result;
}
```

### Why this pattern works
| Feature | How it's handled |
|---|---|
| **Every failure path** | Each critical check (`fopen`, `fseek`/`ftell`, `malloc`, `fread`) immediately jumps to `cleanup`. No resource is assumed valid past its acquisition. |
| **Centralized release** | `cleanup` closes the file and frees the buffer exactly once. |
| **Ownership transfer** | On success, `buf` is assigned to the output parameter and then nulled (`buf = NULL`). The cleanup guard `if (buf) free(buf)` becomes a no-op, preventing double-free. |
| **Readability** | All exit points converge at one spot. Adding/removing resources only requires adding/removing a line before `goto cleanup`. |
| **No leaks** | Every `malloc`/`fopen` has a matching `free`/`fclose` on *every* path (success or failure). |

### Quick usage
```c
char *data = NULL;
size_t n = 0;

if (read_whole_file("config.txt", &data, &n) == 0) {
    /* use data[n] */
    printf("Read %zu bytes\n", n);
    free(data);
} else {
    /* handle error — all resources already released inside the function */
}
```

This is the de facto standard in production C codebases (libraries, OS kernels, game engines) because it gives the safety of RAII-like cleanup without language-level ownership semantics.

Here's a clean, robust C implementation that linearly scans the vocabulary, finds the longest token that prefixes the buffer, and returns its index and consumed length.

```c
#include <string.h>
#include <stddef.h>

/**
 * Greedily matches the longest token from `vocabulary` that is a prefix of `buffer`.
 *
 * @param vocabulary  Array of null-terminated token strings.
 * @param vocab_size  Number of entries in vocabulary.
 * @param buffer      Text buffer to match against (only the start is considered).
 * @param out_token_id   Pointer to store the index of the matching token in vocabulary,
 *                       or -1 if no token matches.
 * @param out_length   Pointer to store the number of characters consumed (token length).
 *
 * @return 0 on success, -1 if no token matches or invalid inputs are given.
 */
int greedy_token_match(const char* vocabulary[], int vocab_size,
                       const char* buffer, int* out_token_id, int* out_length)
{
    if (!vocabulary || !buffer || !out_token_id || !out_length)
        return -1;
    if (vocab_size <= 0)
        return -1;

    int best_id = -1;
    size_t best_len = 0;

    for (int i = 0; i < vocab_size; ++i) {
        const char* token = vocabulary[i];
        if (!token) continue;

        size_t token_len = strlen(token);
        if (token_len == 0) continue;          // skip empty tokens

        /* strncmp compares up to token_len chars.
         * Returns 0 only if buffer starts exactly with token. */
        if (strncmp(buffer, token, token_len) == 0) {
            if (token_len > best_len) {
                best_len = token_len;
                best_id = i;
            }
        }
    }

    if (best_id == -1)
        return -1;

    *out_token_id = best_id;
    *out_length   = (int)best_len;
    return 0;
}
```

### Usage Example
```c
#include <stdio.h>

int main(void) {
    const char* vocab[] = {"hello", "hell", "he", "world", "hi"};
    int vid, len;

    const char* txt1 = "hello world";
    if (greedy_token_match(vocab, 5, txt1, &vid, &len) == 0)
        printf("match: \"%s\" (id=%d, consumed=%d)\n", vocab[vid], vid, len);

    const char* txt2 = "helicopter";
    if (greedy_token_match(vocab, 5, txt2, &vid, &len) == 0)
        printf("match: \"%s\" (id=%d, consumed=%d)\n", vocab[vid], vid, len);
    else
        printf("no match\n");

    return 0;
}
```

### Output
```
match: "hello" (id=0, consumed=5)
match: "he" (id=2, consumed=2)
```

### Design Notes
- **Linear scan** `O(n * L)` where `n` is vocab size and `L` is max token length — fine for typical token vocabularies (a few hundred to a few thousand entries).
- Uses `strncmp` which safely handles buffers shorter than the token (won't falsely match).
- Returns `-1` for no match; `*out_token_id` stays `-1` and `*out_length` stays `0`.
- Skips empty or `NULL` token entries gracefully.
- If multiple tokens share the same maximal length, the first one encountered in the array is returned (deterministic "greedy" behavior).

Here's a C implementation for UTF-8 ↔ UTF-32 conversion with proper error handling:

```c
#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

#define UTF8_MAX_BYTES 4
#define UTF32_REPLACEMENT_CHAR 0xFFFD

// Helper function to get the expected number of bytes in a UTF-8 sequence
// Returns 0 if the byte is invalid as a UTF-8 start byte
static size_t utf8_sequence_length(uint8_t first_byte) {
    if (first_byte < 0x80) {
        return 1;  // 0xxxxxxx
    } else if ((first_byte & 0xE0) == 0xC0) {
        return 2;  // 110xxxxx
    } else if ((first_byte & 0xF0) == 0xE0) {
        return 3;  // 1110xxxx
    } else if ((first_byte & 0xF8) == 0xF0) {
        return 4;  // 11110xxx
    }
    return 0;  // Invalid start byte
}

// Check if a byte is a valid UTF-8 continuation byte (10xxxxxx)
static bool is_utf8_continuation(uint8_t byte) {
    return (byte & 0xC0) == 0x80;
}

// Convert UTF-8 to UTF-32
// Returns: UTF-32 codepoint, or UTF32_REPLACEMENT_CHAR on error
// bytes_consumed: set to number of bytes read from input (or 0 on empty input)
// input: pointer to UTF-8 sequence
// input_length: number of bytes available in input buffer
uint32_t utf8_to_utf32(const uint8_t* input, size_t input_length, 
                       size_t* bytes_consumed) {
    if (input_length == 0) {
        *bytes_consumed = 0;
        return UTF32_REPLACEMENT_CHAR;
    }

    uint32_t codepoint = 0;
    size_t sequence_length = utf8_sequence_length(input[0]);

    if (sequence_length == 0) {
        // Invalid start byte
        *bytes_consumed = 1;
        return UTF32_REPLACEMENT_CHAR;
    }

    if (sequence_length > input_length) {
        // Not enough bytes for the sequence
        *bytes_consumed = input_length;
        return UTF32_REPLACEMENT_CHAR;
    }

    // Validate continuation bytes
    for (size_t i = 1; i < sequence_length; i++) {
        if (!is_utf8_continuation(input[i])) {
            // Invalid continuation byte
            *bytes_consumed = 1;  // Only consume the first invalid byte
            return UTF32_REPLACEMENT_CHAR;
        }
    }

    // Extract codepoint based on sequence length
    switch (sequence_length) {
        case 1:
            codepoint = input[0] & 0x7F;
            break;

        case 2:
            codepoint = (input[0] & 0x1F) << 6;
            codepoint |= (input[1] & 0x3F);
            // Check for overlong encoding
            if (codepoint < 0x80) {
                *bytes_consumed = 2;
                return UTF32_REPLACEMENT_CHAR;
            }
            break;

        case 3:
            codepoint = (input[0] & 0x0F) << 12;
            codepoint |= (input[1] & 0x3F) << 6;
            codepoint |= (input[2] & 0x3F);
            // Check for overlong encoding and surrogate halves
            if (codepoint < 0x800 || 
                (codepoint >= 0xD800 && codepoint <= 0xDFFF)) {
                *bytes_consumed = 3;
                return UTF32_REPLACEMENT_CHAR;
            }
            break;

        case 4:
            codepoint = (input[0] & 0x07) << 18;
            codepoint |= (input[1] & 0x3F) << 12;
            codepoint |= (input[2] & 0x3F) << 6;
            codepoint |= (input[3] & 0x3F);
            // Check for overlong encoding and values > U+10FFFF
            if (codepoint < 0x10000 || codepoint > 0x10FFFF) {
                *bytes_consumed = 4;
                return UTF32_REPLACEMENT_CHAR;
            }
            break;

        default:
            // Shouldn't happen
            *bytes_consumed = 1;
            return UTF32_REPLACEMENT_CHAR;
    }

    *bytes_consumed = sequence_length;
    return codepoint;
}

// Convert UTF-32 to UTF-8
// Returns: number of bytes written to output buffer, or 0 on error
// output: pointer to buffer to write UTF-8 sequence (must have at least UTF8_MAX_BYTES bytes)
// output_buffer_size: size of output buffer in bytes
// codepoint: UTF-32 codepoint to convert
size_t utf32_to_utf8(uint8_t* output, size_t output_buffer_size, uint32_t codepoint) {
    // Check for invalid values
    if (codepoint > 0x10FFFF) {
        return 0;  // Invalid codepoint
    }

    // Check for surrogate halves (0xD800-0xDFFF)
    if (codepoint >= 0xD800 && codepoint <= 0xDFFF) {
        return 0;  // Invalid surrogate
    }

    size_t bytes_needed;
    uint32_t mask, first_byte_mask;

    if (codepoint < 0x80) {
        // 1 byte: 0xxxxxxx
        bytes_needed = 1;
        mask = 0x7F;
        first_byte_mask = 0x00;
    } else if (codepoint < 0x800) {
        // 2 bytes: 110xxxxx 10xxxxxx
        bytes_needed = 2;
        mask = 0x3F;
        first_byte_mask = 0xC0;
    } else if (codepoint < 0x10000) {
        // 3 bytes: 1110xxxx 10xxxxxx 10xxxxxx
        bytes_needed = 3;
        mask = 0x3F;
        first_byte_mask = 0xE0;
    } else {
        // 4 bytes: 11110xxx 10xxxxxx 10xxxxxx 10xxxxxx
        bytes_needed = 4;
        mask = 0x3F;
        first_byte_mask = 0xF0;
    }

    // Check if output buffer is large enough
    if (output_buffer_size < bytes_needed) {
        return 0;
    }

    // Write bytes from least significant to most significant
    for (size_t i = bytes_needed - 1; i > 0; i--) {
        output[i] = 0x80 | (codepoint & mask);
        codepoint >>= 6;
    }

    // Write first byte with appropriate high bits
    output[0] = first_byte_mask | (codepoint & mask);

    return bytes_needed;
}

// Example usage
#include <stdio.h>

int main() {
    // Test UTF-8 to UTF-32
    const uint8_t utf8_test1[] = {0xE4, 0xB8, 0xAD, 0x00};  // 中 (U+4E2D)
    const uint8_t utf8_test2[] = {0xF0, 0x9F, 0x98, 0x80, 0x00};  // 😀 (U+1F600)
    const uint8_t utf8_test3[] = {0xC0, 0xAF, 0x00};  // Invalid: overlong encoding

    size_t consumed;
    uint32_t codepoint;

    printf("UTF-8 to UTF-32 tests:\n");

    codepoint = utf8_to_utf32(utf8_test1, 3, &consumed);
    printf("'中': U+%04X (consumed %zu bytes)\n", codepoint, consumed);

    codepoint = utf8_to_utf32(utf8_test2, 4, &consumed);
    printf("'😀': U+%04X (consumed %zu bytes)\n", codepoint, consumed);

    codepoint = utf8_to_utf32(utf8_test3, 2, &consumed);
    printf("Invalid: U+%04X (consumed %zu bytes)\n", codepoint, consumed);

    // Test UTF-32 to UTF-8
    printf("\nUTF-32 to UTF-8 tests:\n");

    uint8_t buffer[UTF8_MAX_BYTES];
    size_t bytes_written;

    bytes_written = utf32_to_utf8(buffer, UTF8_MAX_BYTES, 0x4E2D);  // 中
    printf("U+4E2D: ");
    for (size_t i = 0; i < bytes_written; i++) {
        printf("0x%02X ", buffer[i]);
    }
    printf("(%zu bytes)\n", bytes_written);

    bytes_written = utf32_to_utf8(buffer, UTF8_MAX_BYTES, 0x1F600);  // 😀
    printf("U+1F600: ");
    for (size_t i = 0; i < bytes_written; i++) {
        printf("0x%02X ", buffer[i]);
    }
    printf("(%zu bytes)\n", bytes_written);

    bytes_written = utf32_to_utf8(buffer, UTF8_MAX_BYTES, 0xD800);  // Surrogate
    printf("U+D800 (surrogate): %zu bytes (should be 0)\n", bytes_written);

    bytes_written = utf32_to_utf8(buffer, UTF8_MAX_BYTES, 0x110000);  // Out of range
    printf("U+110000 (out of range): %zu bytes (should be 0)\n", bytes_written);

    return 0;
}
```

## Key Features:

1. **Safe UTF-8 Decoding** (`utf8_to_utf32`):
   - Validates all bytes in multi-byte sequences
   - Detects overlong encodings (non-canonical forms)
   - Rejects UTF-8 encoded surrogate halves
   - Returns replacement character (U+FFFD) for invalid sequences
   - Reports number of bytes consumed for error recovery

2. **Safe UTF-32 Encoding** (`utf32_to_utf8`):
   - Validates input codepoint range (0x0 to 0x10FFFF)
   - Rejects surrogate halves (0xD800-0xDFFF)
   - Uses correct number of bytes for each range
   - Checks output buffer size

3. **Error Handling**:
   - Invalid UTF-8 start bytes → 1 byte consumed, replacement character
   - Invalid continuation bytes → only invalid bytes consumed
   - Overlong encodings detected and rejected
   - Surrogate halves in either direction rejected
   - Output buffer overflow protection

4. **Compliance**:
   - Follows Unicode Standard (Chapter 3)
   - UTF-8 encoding per RFC 3629
   - Handles all valid Unicode codepoints (U+0 to U+10FFFF)

This implementation is suitable for systems that need robust UTF-8 handling with proper error recovery and validation.

Here's a C function that reads a little-endian uint64 and a varint from a byte buffer with bounds checking:

```c
#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

/**
 * Reads a little-endian uint64 and a varint from a byte buffer with bounds checking.
 * 
 * @param buffer    Pointer to the byte buffer
 * @param buffer_size Total size of the buffer in bytes
 * @param cursor    Pointer to current position in buffer (will be updated)
 * @param out_uint64 Pointer to store the read uint64 value
 * @param out_varint Pointer to store the read varint value
 * @return true on success, false on error (buffer underflow or invalid varint)
 */
bool read_uint64_and_varint(
    const uint8_t *buffer,
    size_t buffer_size,
    size_t *cursor,
    uint64_t *out_uint64,
    uint64_t *out_varint)
{
    // Input validation
    if (!buffer || !cursor || !out_uint64 || !out_varint) {
        return false;
    }

    // Check bounds for uint64 (8 bytes)
    if (*cursor + 8 > buffer_size) {
        return false; // Not enough bytes for uint64
    }

    // Read little-endian uint64
    *out_uint64 = 0;
    for (int i = 0; i < 8; i++) {
        *out_uint64 |= (uint64_t)buffer[*cursor + i] << (i * 8);
    }
    *cursor += 8;

    // Read varint with bounds checking
    *out_varint = 0;
    int shift = 0;

    while (*cursor < buffer_size) {
        uint8_t byte = buffer[*cursor];
        (*cursor)++;

        // Extract 7 bits from current byte
        *out_varint |= (uint64_t)(byte & 0x7F) << shift;

        // If high bit is 0, varint is complete
        if ((byte & 0x80) == 0) {
            break;
        }

        // Prepare for next byte
        shift += 7;

        // Varint overflow protection: max 10 bytes for 64-bit value
        if (shift >= 64) {
            return false; // Varint too long
        }
    }

    // Check if varint reading was complete
    if (*cursor > buffer_size) {
        return false; // Buffer underflow (shouldn't happen with bounds check, but safety)
    }

    return true;
}
```

## Usage Example:

```c
#include <stdio.h>

int main() {
    // Example buffer with uint64 (0x0102030405060708) and varint (300 = 0xAC 0x02)
    uint8_t buffer[] = {
        0x08, 0x07, 0x06, 0x05, 0x04, 0x03, 0x02, 0x01, // uint64
        0xAC, 0x02                                         // varint (300)
    };

    size_t cursor = 0;
    uint64_t uint64_value;
    uint64_t varint_value;

    if (read_uint64_and_varint(buffer, sizeof(buffer), &cursor, 
                               &uint64_value, &varint_value)) {
        printf("Read uint64: 0x%016llX\n", (unsigned long long)uint64_value);
        printf("Read varint: %llu\n", (unsigned long long)varint_value);
        printf("Cursor position: %zu\n", cursor);
    } else {
        printf("Error reading data\n");
    }

    return 0;
}
```

## Key Features:

1. **Bounds Checking**: Verifies that enough bytes are available before reading
2. **Little-Endian**: Correctly reads uint64 in little-endian format
3. **Varint Support**: Implements protocol buffers-style varint encoding
4. **Cursor Advancement**: Automatically updates the cursor position
5. **Error Handling**: Returns false on buffer underflow or malformed varint
6. **Overflow Protection**: Prevents reading more than 10 bytes for varint (max for 64-bit values)
7. **Input Validation**: Checks for null pointers

The varint format uses 7 bits per byte with the MSB as a continuation flag, supporting values from 0 to 2^64-1 with efficient encoding for small numbers.

Here's a minimal JSON tokenizer in C that produces an array of tokens:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Token types
typedef enum {
    TOKEN_STRING,
    TOKEN_NUMBER,
    TOKEN_TRUE,
    TOKEN_FALSE,
    TOKEN_NULL,
    TOKEN_OBJECT_START,
    TOKEN_OBJECT_END,
    TOKEN_ARRAY_START,
    TOKEN_ARRAY_END,
    TOKEN_COLON,
    TOKEN_COMMA,
    TOKEN_ERROR,
    TOKEN_END
} TokenType;

// Token structure
typedef struct {
    TokenType type;
    int start;      // Starting position in input
    int length;     // Length of token
} Token;

// Tokenizer state
typedef struct {
    const char* input;
    int position;
    Token* tokens;
    int tokenCount;
    int tokenCapacity;
} Tokenizer;

// Initialize tokenizer
void initTokenizer(Tokenizer* tokenizer, const char* input) {
    tokenizer->input = input;
    tokenizer->position = 0;
    tokenizer->tokenCount = 0;
    tokenizer->tokenCapacity = 64; // Initial capacity
    tokenizer->tokens = malloc(tokenizer->tokenCapacity * sizeof(Token));
}

// Add token to list
void addToken(Tokenizer* tokenizer, TokenType type, int start, int length) {
    if (tokenizer->tokenCount >= tokenizer->tokenCapacity) {
        tokenizer->tokenCapacity *= 2;
        tokenizer->tokens = realloc(tokenizer->tokens, tokenizer->tokenCapacity * sizeof(Token));
    }

    tokenizer->tokens[tokenizer->tokenCount].type = type;
    tokenizer->tokens[tokenizer->tokenCount].start = start;
    tokenizer->tokens[tokenizer->tokenCount].length = length;
    tokenizer->tokenCount++;
}

// Skip whitespace
void skipWhitespace(Tokenizer* tokenizer) {
    while (tokenizer->input[tokenizer->position] && 
           isspace((unsigned char)tokenizer->input[tokenizer->position])) {
        tokenizer->position++;
    }
}

// Tokenize a string (between quotes)
int tokenizeString(Tokenizer* tokenizer) {
    int start = tokenizer->position;
    tokenizer->position++; // Skip opening quote

    while (tokenizer->input[tokenizer->position] && 
           tokenizer->input[tokenizer->position] != '"') {
        if (tokenizer->input[tokenizer->position] == '\\') {
            tokenizer->position++; // Skip escape character
            if (tokenizer->input[tokenizer->position] == '\0') {
                return -1; // Unexpected end of string
            }
        }
        tokenizer->position++;
    }

    if (tokenizer->input[tokenizer->position] == '\0') {
        return -1; // Unterminated string
    }

    tokenizer->position++; // Skip closing quote
    addToken(tokenizer, TOKEN_STRING, start, tokenizer->position - start);
    return 0;
}

// Tokenize a number
int tokenizeNumber(Tokenizer* tokenizer) {
    int start = tokenizer->position;
    char c = tokenizer->input[tokenizer->position];

    // Optional minus
    if (c == '-') {
        tokenizer->position++;
        c = tokenizer->input[tokenizer->position];
    }

    // Integer part
    if (c == '0') {
        tokenizer->position++;
        c = tokenizer->input[tokenizer->position];
    } else if (isdigit((unsigned char)c)) {
        while (isdigit((unsigned char)tokenizer->input[tokenizer->position])) {
            tokenizer->position++;
        }
        c = tokenizer->input[tokenizer->position];
    } else {
        return -1; // Invalid number
    }

    // Optional fraction
    if (c == '.') {
        tokenizer->position++;
        c = tokenizer->input[tokenizer->position];
        if (!isdigit((unsigned char)c)) {
            return -1; // Digit expected after decimal
        }
        while (isdigit((unsigned char)tokenizer->input[tokenizer->position])) {
            tokenizer->position++;
        }
        c = tokenizer->input[tokenizer->position];
    }

    // Optional exponent
    if (c == 'e' || c == 'E') {
        tokenizer->position++;
        c = tokenizer->input[tokenizer->position];
        if (c == '+' || c == '-') {
            tokenizer->position++;
            c = tokenizer->input[tokenizer->position];
        }
        if (!isdigit((unsigned char)c)) {
            return -1; // Digit expected in exponent
        }
        while (isdigit((unsigned char)tokenizer->input[tokenizer->position])) {
            tokenizer->position++;
        }
    }

    addToken(tokenizer, TOKEN_NUMBER, start, tokenizer->position - start);
    return 0;
}

// Check for literal (true, false, null)
int checkLiteral(Tokenizer* tokenizer, const char* literal, TokenType type) {
    int len = strlen(literal);
    if (strncmp(&tokenizer->input[tokenizer->position], literal, len) == 0) {
        tokenizer->position += len;
        addToken(tokenizer, type, tokenizer->position - len, len);
        return 0;
    }
    return -1;
}

// Main tokenizer function
Token* tokenize(const char* json, int* tokenCount) {
    Tokenizer tokenizer;
    initTokenizer(&tokenizer, json);

    while (tokenizer.input[tokenizer.position] != '\0') {
        skipWhitespace(&tokenizer);

        char c = tokenizer.input[tokenizer.position];
        if (c == '\0') break; // End of input

        switch (c) {
            case '{':
                addToken(&tokenizer, TOKEN_OBJECT_START, tokenizer.position, 1);
                tokenizer.position++;
                break;
            case '}':
                addToken(&tokenizer, TOKEN_OBJECT_END, tokenizer.position, 1);
                tokenizer.position++;
                break;
            case '[':
                addToken(&tokenizer, TOKEN_ARRAY_START, tokenizer.position, 1);
                tokenizer.position++;
                break;
            case ']':
                addToken(&tokenizer, TOKEN_ARRAY_END, tokenizer.position, 1);
                tokenizer.position++;
                break;
            case ':':
                addToken(&tokenizer, TOKEN_COLON, tokenizer.position, 1);
                tokenizer.position++;
                break;
            case ',':
                addToken(&tokenizer, TOKEN_COMMA, tokenizer.position, 1);
                tokenizer.position++;
                break;
            case '"':
                if (tokenizeString(&tokenizer) != 0) {
                    addToken(&tokenizer, TOKEN_ERROR, tokenizer.position, 0);
                    tokenizer.position++;
                }
                break;
            case 't':
                if (checkLiteral(&tokenizer, "true", TOKEN_TRUE) != 0) {
                    addToken(&tokenizer, TOKEN_ERROR, tokenizer.position, 1);
                    tokenizer.position++;
                }
                break;
            case 'f':
                if (checkLiteral(&tokenizer, "false", TOKEN_FALSE) != 0) {
                    addToken(&tokenizer, TOKEN_ERROR, tokenizer.position, 1);
                    tokenizer.position++;
                }
                break;
            case 'n':
                if (checkLiteral(&tokenizer, "null", TOKEN_NULL) != 0) {
                    addToken(&tokenizer, TOKEN_ERROR, tokenizer.position, 1);
                    tokenizer.position++;
                }
                break;
            default:
                if (c == '-' || isdigit((unsigned char)c)) {
                    if (tokenizeNumber(&tokenizer) != 0) {
                        addToken(&tokenizer, TOKEN_ERROR, tokenizer.position, 1);
                        tokenizer.position++;
                    }
                } else {
                    // Unknown character
                    addToken(&tokenizer, TOKEN_ERROR, tokenizer.position, 1);
                    tokenizer.position++;
                }
                break;
        }
    }

    addToken(&tokenizer, TOKEN_END, tokenizer.position, 0);
    *tokenCount = tokenizer.tokenCount;
    return tokenizer.tokens;
}

// Example usage
int main() {
    const char* json = "{\"name\": \"John\", \"age\": 30, \"active\": true}";
    int tokenCount;
    Token* tokens = tokenize(json, &tokenCount);

    // Token type names for output
    const char* tokenTypeNames[] = {
        "STRING", "NUMBER", "TRUE", "FALSE", "NULL",
        "OBJECT_START", "OBJECT_END", "ARRAY_START", "ARRAY_END",
        "COLON", "COMMA", "ERROR", "END"
    };

    printf("Input: %s\n\n", json);
    printf("Tokens:\n");
    for (int i = 0; i < tokenCount; i++) {
        printf("%2d: %-12s [%d..%d] \"", i, 
               tokenTypeNames[tokens[i].type], 
               tokens[i].start, 
               tokens[i].start + tokens[i].length - 1);

        // Print token content (safely)
        for (int j = 0; j < tokens[i].length; j++) {
            putchar(json[tokens[i].start + j]);
        }
        printf("\"\n");
    }

    // Free memory
    free(tokens);

    return 0;
}
```

## Key Features:

1. **Token Types**: Supports all JSON tokens - strings, numbers, booleans (true/false), null, objects, arrays, and separators.

2. **Token Structure**: Each token stores:
   - `type`: Token type enum
   - `start`: Starting position in the input string
   - `length`: Length of the token

3. **String Handling**: Properly handles escape sequences (like `\"`, `\\`, `\/`, `\b`, `\f`, `\n`, `\r`, `\t`, `\uXXXX`).

4. **Number Handling**: Supports JSON number format including optional minus, decimal point, and exponents.

5. **Memory Management**: Dynamically grows the token array as needed.

## Sample Output:
```
Input: {"name": "John", "age": 30, "active": true}

Tokens:
 0: OBJECT_START  [0..0]  "{"
 1: STRING        [1..5]  "name"
 2: COLON         [6..6]  ":"
 3: STRING        [8..12] "John"
 4: COMMA         [13..13] ","
 5: STRING        [15..17] "age"
 6: COLON         [18..18] ":"
 7: NUMBER        [20..21] "30"
 8: COMMA         [22..22] ","
 9: STRING        [24..29] "active"
10: COLON         [30..30] ":"
11: TRUE          [32..35] "true"
12: OBJECT_END    [36..36] "}"
13: END           [37..36] ""
```

This tokenizer is minimal but handles valid JSON correctly. It doesn't validate JSON structure (e.g., mismatched braces), but that's typically the job of a parser, not a tokenizer.

In C, swapping two integer values and swapping two integer pointers require different operations because they modify different levels of indirection. Let me explain and implement both functions.

## 1. Swapping Two Integer Values (`int*`)

This function swaps the actual integer values stored at the memory locations pointed to by two `int*` pointers.

```c
#include <stdio.h>

void swap_ints(int* a, int* b) {
    if (a == NULL || b == NULL) return;  // Safety check
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main() {
    int x = 10;
    int y = 20;

    printf("Before swap: x = %d, y = %d\n", x, y);
    swap_ints(&x, &y);  // Pass addresses of x and y
    printf("After swap:  x = %d, y = %d\n", x, y);

    return 0;
}
```

**Output:**
```
Before swap: x = 10, y = 20
After swap:  x = 20, y = 10
```

## 2. Swapping Two Integer Pointers (`int**`)

This function swaps the pointers themselves, so that after the call, the first pointer points to what the second pointed to, and vice versa.

```c
#include <stdio.h>

void swap_ptrs(int** a, int** b) {
    if (a == NULL || b == NULL) return;  // Safety check
    int* temp = *a;
    *a = *b;
    *b = temp;
}

int main() {
    int val1 = 100;
    int val2 = 200;
    int* ptr1 = &val1;
    int* ptr2 = &val2;

    printf("Before swap: ptr1 -> %d, ptr2 -> %d\n", *ptr1, *ptr2);
    swap_ptrs(&ptr1, &ptr2);  // Pass addresses of ptr1 and ptr2
    printf("After swap:  ptr1 -> %d, ptr2 -> %d\n", *ptr1, *ptr2);

    return 0;
}
```

**Output:**
```
Before swap: ptr1 -> 100, ptr2 -> 200
After swap:  ptr1 -> 200, ptr2 -> 100
```

## Why They're Different

### Key Differences:

1. **Level of Indirection:**
   - `swap_ints(int* a, int* b)`: Works with pointers to integers. Changes what the pointers *point to*.
   - `swap_ptrs(int** a, int** b)`: Works with pointers to pointers to integers. Changes the pointers *themselves*.

2. **What Gets Swapped:**
   - `swap_ints` swaps the **values stored in memory** that the pointers reference.
   - `swap_ptrs` swaps **the pointers themselves**, so they point to different memory locations.

3. **Parameters:**
   - `swap_ints` takes two `int*` parameters.
   - `swap_ptrs` takes two `int**` parameters (pointers to the pointers to be swapped).

### Visual Explanation:

```
Example 1: swap_ints(&x, &y)
Before: x (10) ← ptr1    y (20) ← ptr2
After:  x (20) ← ptr1    y (10) ← ptr2
(ptr1 and ptr2 still point to x and y, but the values at those locations are swapped)

Example 2: swap_ptrs(&ptr1, &ptr2)
Before: ptr1 → val1 (100), ptr2 → val2 (200)
After:  ptr1 → val2 (200), ptr2 → val1 (100)
(the pointers themselves are swapped, so they now point to different variables)
```

### When to Use Each:

- **`swap_ints`**: Use when you want to exchange the actual data stored in two integer variables.
- **`swap_ptrs`**: Use when you want to change which variables two pointers reference. This is useful for:
  - Reassigning pointers without manually copying addresses
  - Implementing algorithms that need to swap pointer references (like in sorting arrays of pointers)
  - Changing which object a pointer refers to in more complex data structures

### Common Pitfall:

A common mistake is to try to swap pointers in a function like this:
```c
void wrong_swap(int* a, int* b) {
    int* temp = a;
    a = b;
    b = temp;
}
```
This won't work because it only swaps the *local copies* of the pointers, not the original pointers in the calling function. To swap the actual pointers, you need to pass their addresses (`int**`), as shown in `swap_ptrs`.

Here's a memory-efficient Node.js function that streams a file line-by-line using the built-in `readline` module, attempts to parse each line as JSON, and counts how many lines fail to parse.

```js
const fs = require('fs');
const readline = require('readline');

/**
 * Counts lines that fail JSON.parse in a large file.
 * Uses streaming to avoid loading the entire file into memory.
 *
 * @param {string} filePath - Path to the file (e.g., JSONL format)
 * @returns {Promise<number>} - Count of lines that failed JSON parsing
 */
async function countJsonParseErrors(filePath) {
  let errorCount = 0;
  const rl = readline.createInterface({
    input: fs.createReadStream(filePath, { encoding: 'utf8' }),
    crlfDelay: Infinity // Handles both \n and \r\n line endings
  });

  for await (const line of rl) {
    // Skip completely empty lines (optional – remove if you want them counted as errors)
    if (line.trim() === '') continue;

    try {
      JSON.parse(line);
    } catch (e) {
      errorCount++;
    }
  }

  return errorCount;
}

// Example usage:
/*
countJsonParseErrors('largefile.jsonl')
  .then(count => console.log(`JSON parse errors: ${count}`))
  .catch(err => console.error('Error reading file:', err));
*/
```

**Why this works:**
- `fs.createReadStream()` + `readline.createInterface()` reads the file line-by-line as a stream, so only one line lives in memory at a time.
- `for await (const line of rl)` iterates asynchronously without buffering the whole file.
- `JSON.parse(line)` inside a `try/catch` counts every line that isn't valid JSON.
- `crlfDelay: Infinity` ensures compatibility with both Unix and Windows line endings.
- Empty/whitespace-only lines are skipped by default (remove the `if` block if you'd prefer them counted as parse errors).
